// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/inter";
import "@fontsource/noto-sans-kr";

export const inter = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the scroll target, normalized to 60fps. */
const OPEN_LERP = 0.14;

/**
 * Drives `--bloom-open` (0 → 1) on the referenced element based on how far
 * the viewport has scrolled through the element's own height — the pinned
 * "the bloom" section. As you scroll the pinned flower stays put while
 * `--bloom-open` rises from 0 (a closed bud, petals scaled to 0.42 and
 * rotated -8°) to 1 (fully open, petals at scale 1, rotation 0°). The
 * section's height in CSS is taller than the viewport on purpose (a sticky
 * inner), so the progress maps cleanly onto a few screens of scroll.
 *
 * The CSS fallback is `var(--bloom-open, 1)` — fully open — so without
 * JavaScript, and under reduced motion (where this hook does nothing), the
 * signature flower simply stands open. The lerp makes it scrubbable without
 * jitter: scrolling fast opens fast, scrolling slow opens slow, and
 * scrolling back up closes the flower again.
 *
 * The scroll handler is passive and only writes to a CSS custom property
 * (no layout work); the rAF loop runs only while the section is on screen
 * and the tab is visible.
 */
export function useScrollProgress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;

    el.style.setProperty("--bloom-open", "0");

    let raf = 0;
    let running = false;
    let inView = true;
    let value = 0;
    let last = 0;
    let target = 0;

    const computeTarget = () => {
      const rect = el.getBoundingClientRect();
      // Progress is how far the section's top has traveled from "just
      // entered at the bottom" to "its content has scrolled past". We pin
      // via position: sticky in CSS, so the visible flower stays fixed
      // while this number climbs.
      const total = rect.height - window.innerHeight;
      if (total <= 0) {
        target = 1;
        return;
      }
      // When the section top is at or above the viewport top, progress
      // starts; it completes when the section's bottom reaches the fold.
      const traveled = Math.min(Math.max(-rect.top, 0), total);
      target = traveled / total;
    };

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const next = value + (target - value) * OPEN_LERP * (dt / 16.7);
      if (Math.abs(next - value) < 0.0002) return;
      value = next;
      el.style.setProperty("--bloom-open", value.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      computeTarget();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onScroll = () => {
      if (inView && !document.hidden) computeTarget();
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      document.removeEventListener("visibilitychange", onVisibility);
      // hand the element back to the CSS fallback (fully open)
      el.style.removeProperty("--bloom-open");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { inter, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useScrollProgress } from "./hooks/useScrollProgress";
import { usePointerParallax } from "./hooks/usePointerParallax";

const TITLE = "RIP";

/**
 * RIP — 파문, 잉크 파문 연못. Ink-bloom entry where ink ripples expand
 * from pointer touches on a still pond surface. canvas-particles (the
 * ripple ring system), pointer-parallax (depth layers shift), scroll-scrub-
 * pinned (a verse section where ripples intensify with scroll).
 */
export default function RipPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const verseRef = useScrollProgress<HTMLDivElement>(reduced);
  const pondRef = usePointerParallax<HTMLDivElement>(reduced);
  const ripples = useRef<{ x: number; y: number; r: number; life: number }[]>([]);

  useEffect(() => {
    rootRef.current?.classList.add("rip-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "rip" }, "*");

    if (reduced) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const resize = () => {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
    };
    resize();
    window.addEventListener("resize", resize);

    // ambient auto-ripple every 3s
    const ambient = window.setInterval(() => {
      ripples.current.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        r: 0,
        life: 1,
      });
    }, 3000);

    let raf = 0;
    const draw = () => {
      raf = requestAnimationFrame(draw);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ripples.current = ripples.current.filter((rp) => rp.life > 0);
      for (const rp of ripples.current) {
        rp.r += 1.5;
        rp.life -= 0.008;
        ctx.beginPath();
        ctx.arc(rp.x, rp.y, rp.r, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(124, 58, 237, ${rp.life * 0.5})`;
        ctx.lineWidth = 2;
        ctx.stroke();
        // inner ring
        if (rp.r > 10) {
          ctx.beginPath();
          ctx.arc(rp.x, rp.y, rp.r - 8, 0, Math.PI * 2);
          ctx.strokeStyle = `rgba(79, 70, 229, ${rp.life * 0.3})`;
          ctx.lineWidth = 1;
          ctx.stroke();
        }
      }
    };
    raf = requestAnimationFrame(draw);

    const onPointer = (ev: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      ripples.current.push({
        x: ev.clientX - rect.left,
        y: ev.clientY - rect.top,
        r: 0,
        life: 1,
      });
    };
    canvas.addEventListener("pointerdown", onPointer);

    return () => {
      window.clearInterval(ambient);
      window.removeEventListener("resize", resize);
      cancelAnimationFrame(raf);
      canvas.removeEventListener("pointerdown", onPointer);
    };
  }, [reduced]);

  return (
    <div ref={rootRef} className={`${inter.variable} ${notoSansKR.variable} rip-root`}>
      <div ref={revealRef} className="rip-doc">
        <header className="rip-hero">
          <p className="rip-kicker"><span lang="ko">잉크 파문 연못</span> · INK RIPPLE POND</p>
          <h1 className="rip-title" aria-label="RIP 파문">
            {TITLE.split("").map((ch, i) => (
              <span key={i} aria-hidden="true" className="rip-glyph" style={{ "--rip-i": i } as CSSProperties}>{ch}</span>
            ))}
          </h1>
          <p className="rip-title__ko" lang="ko">파문</p>
          <p className="rip-sub"><span lang="ko">손길에 잉크가 퍼진다. 연못을 건드려 보라.</span> Ink ripples from touch. Touch the pond.</p>
        </header>

        {/* canvas-particles: the ripple pond */}
        <section ref={pondRef} className="rip-pond" data-reveal="">
          <canvas ref={canvasRef} className="rip-pond__canvas" aria-label="Interactive ink ripple pond — click to ripple" />
          <p className="rip-pond__hint"><span lang="ko">연못을 클릭하면 잉크가 번진다</span> · click the pond to ripple</p>
        </section>

        {/* scroll-scrub-pinned: the verse */}
        <section ref={verseRef} className="rip-verse" data-reveal="">
          <p className="rip-verse__line" lang="ko">한 방울이 떨어지면</p>
          <p className="rip-verse__line" lang="ko">연못 전체가 응답한다</p>
          <p className="rip-verse__en"><em>One drop falls — the whole pond answers.</em></p>
        </section>

        <footer className="rip-foot" data-reveal="">
          <p>© 2026 RIP · <span lang="ko">파문</span> · MIT</p>
          <p><span lang="ko">잔잔 — 코드로 그렸다.</span> still water — drawn in code.</p>
        </footer>
      </div>
    </div>
  );
}

/* RIP 파문 — ink ripple pond · ink-bloom
   pond white / violet ink / indigo ripple · generative concentric rings */

.rip-root {
  --rip-bg: #f5f3ff;
  --rip-bg-deep: #ede9fe;
  --rip-ink: #1e1b4b;
  --rip-ink-soft: #4c1d95;
  --rip-violet: #7c3aed;
  --rip-indigo: #4f46e5;

  position: relative;
  min-height: 100vh;
  background: linear-gradient(180deg, var(--rip-bg) 0%, var(--rip-bg-deep) 100%);
  color: var(--rip-ink);
  font-family: "Inter", "Noto Sans KR", sans-serif;
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.75;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Faint concentric waterlines — the pond's surface remembered as rings,
   drifting very slowly. Pure CSS; the canvas carries the live ripples. */
.rip-root::before {
  content: "";
  position: fixed;
  inset: -10%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 30% 40%, transparent 0, transparent 80px, rgba(124,58,237,0.05) 81px, transparent 82px),
    radial-gradient(circle at 30% 40%, transparent 0, transparent 140px, rgba(124,58,237,0.04) 141px, transparent 142px),
    radial-gradient(circle at 70% 65%, transparent 0, transparent 100px, rgba(79,70,229,0.04) 101px, transparent 102px);
  animation: rip-drift 26s ease-in-out infinite alternate;
}
@keyframes rip-drift {
  to { transform: translate3d(2%, -1.5%, 0); }
}
@media (prefers-reduced-motion: reduce) {
  .rip-root::before { animation: none; }
}

.rip-root :lang(ko) { font-family: "Noto Sans KR", sans-serif; }
.rip-root ::selection { background: var(--rip-violet); color: #fff; }
.rip-root :focus-visible { outline: 2px solid var(--rip-violet); outline-offset: 4px; }

.rip-js [data-reveal] {
  opacity: 0; transform: translateY(24px);
  transition: opacity 900ms cubic-bezier(0.16,1,0.3,1), transform 900ms cubic-bezier(0.16,1,0.3,1);
}
.rip-js [data-reveal].is-visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .rip-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

.rip-doc { position: relative; z-index: 1; }

/* Hero */
.rip-hero {
  padding: clamp(80px, 16vh, 140px) clamp(20px, 5vw, 60px) clamp(40px, 8vh, 60px);
  text-align: center;
}
.rip-kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--rip-violet);
  margin: 0 0 30px;
}
.rip-title {
  font-weight: 700;
  font-size: clamp(4rem, 14vw, 9rem);
  line-height: 0.9;
  margin: 0 0 8px;
  display: flex;
  justify-content: center;
  gap: 0.02em;
}
.rip-glyph {
  display: inline-block;
  color: var(--rip-violet);
  opacity: 0;
  transform: scale(0);
}
.rip-js .rip-glyph {
  animation: rip-glyph 600ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
  animation-delay: calc(var(--rip-i, 0) * 130ms + 200ms);
}
@keyframes rip-glyph { to { opacity: 1; transform: scale(1); } }
@media (prefers-reduced-motion: reduce) {
  .rip-glyph { opacity: 1; transform: none; animation: none; }
}
.rip-title__ko {
  font-size: clamp(1rem, 2vw, 1.5rem);
  color: var(--rip-ink-soft);
  margin: 0 0 24px;
}
.rip-sub { color: var(--rip-ink-soft); margin: 0; }

/* canvas-particles: the ripple pond — pointer-parallax */
.rip-pond {
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
  transition: transform 500ms cubic-bezier(0.16,1,0.3,1);
  will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
  .rip-pond { transform: none !important; transition: none; }
}
.rip-pond__canvas {
  width: 100%;
  height: 400px;
  border-radius: 20px;
  background: radial-gradient(ellipse at center, var(--rip-bg) 0%, var(--rip-bg-deep) 100%);
  border: 1px solid rgba(124,58,237,0.15);
  cursor: crosshair;
  display: block;
}
.rip-pond__hint {
  margin: 20px 0 0;
  color: var(--rip-ink-soft);
  font-size: 0.85rem;
}

/* scroll-scrub-pinned: the verse */
.rip-verse {
  position: sticky;
  top: 0;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
  background: var(--rip-bg-deep);
  border-top: 1px solid rgba(124,58,237,0.15);
  border-bottom: 1px solid rgba(124,58,237,0.15);
}
.rip-verse__line {
  font-size: clamp(1.8rem, 5vw, 3rem);
  font-weight: 600;
  color: var(--rip-violet);
  margin: 0 0 16px;
  opacity: calc(0.3 + var(--rip-scrub, 0.5) * 0.7);
  transform: translateY(calc((1 - var(--rip-scrub, 0.5)) * 30px));
  transition: opacity 200ms, transform 200ms;
}
.rip-verse__en {
  font-style: italic;
  color: var(--rip-ink-soft);
  margin: 24px 0 0;
  font-size: clamp(0.9rem, 1.5vw, 1.05rem);
}

/* Footer */
.rip-foot {
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  text-align: center;
  color: var(--rip-ink-soft);
  font-size: 0.82rem;
}
.rip-foot p { margin: 0 0 6px; }
